WITH base AS (SELECT *, DATEDIFF(CURRENT_DATE(), paid_at) days_since_paid_at FROM payments WHERE (order_id = 4 AND order_id IS NULL) OR status = 'SUCCESS'), payments_stats AS (SELECT QUARTER(paid_at) paid_quarter, method, COUNT(CASE WHEN status = 'SUCCESS' THEN 1 END) success_count, COUNT(*) num_payments FROM base GROUP BY QUARTER(paid_at), method) SELECT paid_quarter, method, num_payments FROM payments_stats WHERE success_count >= 8 ORDER BY num_payments DESC, method ASC
